  // Spec (#1464): store only when it is a valid/implemented command.
  // Runtime failures (e.g., :e path-not-found) are still stored; unknown commands are not.
  function _cmdHistoryShouldPush(s){
    try{
      let v = String(s||'').trim();
      if (!v || v === ':') return false;
      // Normalize optional leading ':'
      if (!/^\s*:/.test(v)) v = ':' + v;

      // Search prompts: /... or ? ... (cmdinput may include leading ':')
      if (/^:\s*[\/?].+/.test(v) || /^\s*[\/?].+/.test(String(s||'').trim())) return true;

      // Implemented ex-commands (broad-but-safe match based on runCommand handlers)
      if (/^:\s*e!?\b/i.test(v)) return true;
      if (/^:\s*grep\b/i.test(v)) return true;
      if (/^:?[\s]*(%|'<,'>)?\s*s(?:ubstitute)?\//i.test(v)) return true;
      if (/^:\s*help\b/i.test(v)) return true;
      if (/^:\s*b\b/i.test(v)) return true;
      if (/^:\s*\d+\s*$/.test(v)) return true;
      if (/^:\s*q!?\s*$/i.test(v) || /^:\s*quit\s*$/i.test(v)) return true;
      if (/^:\s*qa\s*$/i.test(v) || /^:\s*quitall\s*$/i.test(v)) return true;
      if (/^:\s*(?:w|wa|wq|wqa)!?\b/i.test(v)) return true;
      // Only store implemented :set family (we treat any :set as valid since it's a single command surface)
      if (/^:\s*set\b/i.test(v)) return true;

      // Utility/debug commands implemented in runCommand
      if (/^:\s*reload\s*$/i.test(v)) return true;
      if (/^:\s*pick!?\s*$/i.test(v)) return true;
      if (/^:\s*api\?\s*$/i.test(v)) return true;
      if (/^:\s*echo\s+api\s*$/i.test(v)) return true;
      if (/^:\s*build\??\s*$/i.test(v)) return true;
      if (/^:\s*colorpicker\s*$/i.test(v)) return true;
      if (/^:\s*(?:lastsynctime|statmeta!?|parentnav|dumpkeys|dumprawkeys|clearkeys|clearrawkeys)\b/i.test(v)) return true;

      return false;
    }catch{ return false; }
  }

  // Popup mouse-hide helper (#1601)
  // Purpose: when a popup opens or when ArrowUp/Down is pressed, hide the mouse cursor temporarily
  // and disable hover (pointer events) on popups so a stationary pointer cannot steal selection.
  let _sixMouseHidden = false;
  let _sixMouseHideInit = false;
  function _sixEnsureMouseHideForPopups(){
    try{
      if (_sixMouseHideInit) return;
      _sixMouseHideInit = true;

      // Inject minimal CSS once.
      try{
        let st = document.getElementById('six-mouse-hide-css');
        if (!st){
          st = document.createElement('style');
          st.id = 'six-mouse-hide-css';
          (document.head || document.documentElement || document.body).appendChild(st);
        }
        // Always refresh the content so hot-updates don't leave an old rule behind.
        st.textContent = [
          // Hide cursor globally while active.
          'body.six-mouse-hidden, body.six-mouse-hidden * { cursor: none !important; }'
        ].join('\n');
      }catch{}

      const show = ()=>{ try{ _sixMouseHidden = false; document.body && document.body.classList && document.body.classList.remove('six-mouse-hidden'); }catch{} };
      const onAny = ()=>{ try{ if (_sixMouseHidden) show(); }catch{} };

      const _add = (target, type)=>{
        try{
          if (!target || !target.addEventListener) return;
          try{ target.addEventListener(type, onAny, { passive:true, capture:true }); return; }catch{}
          try{ target.addEventListener(type, onAny, true); }catch{}
        }catch{}
      };

      // Any real pointing interaction brings the cursor back.
      // Use both window and document: some hosts dispatch pointer/mouse events differently.
      const targets = [window, document];
      for (const t of targets){
        _add(t, 'mousemove');
        _add(t, 'mousedown');
        _add(t, 'wheel');
        _add(t, 'pointermove');
        _add(t, 'pointerdown');
        _add(t, 'touchstart');
        _add(t, 'touchmove');
      }
    }catch{}
  }
