            const top = container.scrollTop;
            const h = container.clientHeight || 0;
            const margin = Math.floor(h * 0.35);
            const et = el.offsetTop;
            const eb = et + (el.offsetHeight||0);
            const min = top + margin;
            const max = top + h - margin;
